const r = ($input.first().json.report) || {};
const p24 = r.period_24h || {calls:0,cost:0,errors:0};
const p7  = r.period_7d  || {calls:0,cost:0,errors:0};
const p30 = r.period_30d || {calls:0,cost:0,errors:0,agents_active:0};
const byAgent = Array.isArray(r.by_agent_30d) ? r.by_agent_30d : [];
const byModel = Array.isArray(r.by_model_30d) ? r.by_model_30d : [];
const unknownCount = Number(r.unknown_agent_24h || 0);

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function money(n) { return '$' + (Number(n||0)).toFixed(4); }
function money2(n) { return '$' + (Number(n||0)).toFixed(2); }
function dateShort(s) { if (!s) return '-'; const d = new Date(s); return d.toISOString().substring(0,16).replace('T',' '); }

const rowsAgent = byAgent.map(a => {
  const isUnknown = ['unknown_agent','unknown',''].includes(a.agent_name);
  const cls = isUnknown ? ' style="background:#fee"' : '';
  const errCls = (Number(a.errors_30d||0) > 0) ? ' style="color:#c00;font-weight:600"' : '';
  return `<tr${cls}>
    <td>${esc(a.agent_name)}</td>
    <td style="text-align:right">${a.calls_30d}</td>
    <td style="text-align:right">${money(a.cost_30d)}</td>
    <td style="text-align:right"${errCls}>${a.errors_30d}</td>
    <td style="text-align:right">${a.latency_ms_avg}</td>
    <td style="text-align:right">${a.tokens_total}</td>
    <td>${dateShort(a.last_call_at)}</td>
  </tr>`;
}).join('');

const rowsModel = byModel.map(m => `<tr><td>${esc(m.model)}</td><td style="text-align:right">${m.calls}</td><td style="text-align:right">${money(m.cost_30d)}</td></tr>`).join('');

const alertBanner = unknownCount > 0
  ? `<div style="background:#fee;border:2px solid #c00;padding:12px 16px;border-radius:6px;margin-bottom:18px"><strong>ALERTA:</strong> ${unknownCount} llamadas con agent_name='unknown_agent' en las ultimas 24h. Revisar agentes recientes (cron_unknown_agent_alert deberia haber enviado email).</div>`
  : '';

const html = `<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="utf-8"><title>LLM Stats - ArquitAI</title>
<style>
  body{font-family:system-ui,sans-serif;max-width:1200px;margin:32px auto;padding:0 20px;color:#222;background:#f7f7f8}
  h1{margin:0 0 24px}
  h2{margin:32px 0 12px;font-size:18px;border-bottom:1px solid #ddd;padding-bottom:6px}
  .cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:24px}
  .card{background:#fff;border:1px solid #ddd;border-radius:8px;padding:16px}
  .card h3{margin:0 0 8px;font-size:13px;color:#666;text-transform:uppercase}
  .card .v{font-size:24px;font-weight:600}
  .card .sub{font-size:12px;color:#888;margin-top:4px}
  table{width:100%;border-collapse:collapse;background:#fff;border:1px solid #ddd;border-radius:8px;overflow:hidden}
  th,td{padding:8px 12px;border-bottom:1px solid #eee;font-size:14px;text-align:left}
  th{background:#f0f0f3;font-weight:600}
  tr:last-child td{border-bottom:none}
  .meta{font-size:12px;color:#888;margin-top:24px}
</style>
</head>
<body>
<h1>LLM Stats - ArquitAI</h1>
${alertBanner}
<div class="cards">
  <div class="card"><h3>Ultimas 24h</h3><div class="v">${p24.calls} calls</div><div class="sub">${money(p24.cost)} - ${p24.errors} errores</div></div>
  <div class="card"><h3>Ultimos 7d</h3><div class="v">${p7.calls} calls</div><div class="sub">${money(p7.cost)} - ${p7.errors} errores</div></div>
  <div class="card"><h3>Ultimos 30d</h3><div class="v">${p30.calls} calls</div><div class="sub">${money(p30.cost)} - ${p30.errors} errores - ${p30.agents_active} agentes</div></div>
</div>
<h2>Por agente (30d) - ordenado por coste</h2>
<table>
  <thead><tr><th>agent_name</th><th style="text-align:right">calls</th><th style="text-align:right">cost</th><th style="text-align:right">errors</th><th style="text-align:right">latency_ms</th><th style="text-align:right">tokens</th><th>ultima call</th></tr></thead>
  <tbody>${rowsAgent || '<tr><td colspan="7" style="text-align:center;color:#888">Sin datos en ventana 30d</td></tr>'}</tbody>
</table>
<h2>Por modelo (30d)</h2>
<table>
  <thead><tr><th>model</th><th style="text-align:right">calls</th><th style="text-align:right">cost</th></tr></thead>
  <tbody>${rowsModel || '<tr><td colspan="3" style="text-align:center;color:#888">Sin datos</td></tr>'}</tbody>
</table>
<div class="meta">Generado ${new Date().toISOString()} - fuente: tabla llm_calls (vista llm_costs_summary)</div>
</body></html>`;

return [{ json: { html } }];
